-- =============================================================================
-- MediCheck MASTER SCHEMA  (generated by `npm run build:schema` - do not edit by hand)
-- Contains migrations: 0001, 0002, 0003, 0004, 0005, 0006, 0007
-- Safe on a brand-new Supabase project AND on a project that already ran 0001-0004:
-- every statement is idempotent (IF NOT EXISTS / CREATE OR REPLACE / DROP ... IF EXISTS).
-- Paste the whole file into Supabase > SQL Editor > Run.
-- =============================================================================

-- #############################################################################
-- ## 0001_schema.sql
-- #############################################################################

-- =============================================================================
-- MediCheck Migration 0001: Core Schema & Indexes
-- =============================================================================

-- Enable required extensions
create extension if not exists pgcrypto;
create extension if not exists pg_trgm;

-- 1. brand_products
create table if not exists public.brand_products (
    id uuid primary key default gen_random_uuid(),
    brand_name text not null,
    manufacturer text not null,
    salt_normalized text not null,
    strength text not null,
    dosage_form text not null,
    pack_size numeric not null check (pack_size > 0),
    pack_unit text not null,
    printed_mrp numeric not null check (printed_mrp >= 0),
    price_per_unit numeric not null check (price_per_unit >= 0),
    mrp_source text,
    mrp_date date,
    schedule_status text not null default 'unknown'
        check (schedule_status in ('scheduled', 'non_scheduled', 'unknown')),
    notes text,
    created_at timestamptz not null default now()
);

-- 2. barcodes
create table if not exists public.barcodes (
    barcode text primary key,
    barcode_type text,
    brand_product_id uuid not null references public.brand_products(id) on delete cascade,
    pack_size numeric,
    source text,
    notes text,
    created_at timestamptz not null default now()
);

-- 3. ceiling_prices (NPPA DPCO ceiling prices)
create table if not exists public.ceiling_prices (
    id uuid primary key default gen_random_uuid(),
    salt_normalized text not null,
    strength text not null,
    dosage_form text not null,
    pack_unit text not null,
    ceiling_price numeric not null check (ceiling_price >= 0),
    gst_note text,
    effective_date date,
    notification_ref text,
    source_url text,
    source_date date,
    notes text,
    created_at timestamptz not null default now()
);

-- 4. nsq_alerts (CDSCO / State FDA Not of Standard Quality & Spurious alerts)
create table if not exists public.nsq_alerts (
    id uuid primary key default gen_random_uuid(),
    alert_month text not null,
    category text not null check (category in ('NSQ', 'SPURIOUS')),
    drug_name text not null,
    salt_normalized text not null,
    brand_name text,
    batch_number text not null,
    batch_key text generated always as (upper(regexp_replace(batch_number, '\s', '', 'g'))) stored,
    manufacturer text,
    manufacturing_date text,
    expiry_date text,
    failure_reason text,
    testing_lab text,
    source_url text,
    source_date date,
    notes text,
    created_at timestamptz not null default now()
);

-- 5. jan_aushadhi_products (PMBJP generic products)
create table if not exists public.jan_aushadhi_products (
    id uuid primary key default gen_random_uuid(),
    ja_product_code text not null unique,
    generic_name text not null,
    salt_normalized text not null,
    strength text not null,
    dosage_form text not null,
    pack_size numeric not null check (pack_size > 0),
    pack_unit text not null,
    mrp numeric not null check (mrp >= 0),
    price_per_unit numeric not null check (price_per_unit >= 0),
    source_url text,
    source_date date,
    notes text,
    created_at timestamptz not null default now()
);

-- 6. authorities (NPPA, CDSCO, State FDAs)
create table if not exists public.authorities (
    id uuid primary key default gen_random_uuid(),
    authority_name text not null,
    authority_type text not null,
    state text,
    complaint_url text,
    email text,
    phone text,
    handles text,
    source_url text,
    source_date date,
    notes text,
    created_at timestamptz not null default now()
);

-- 7. data_versions (dataset freshness tracking)
create table if not exists public.data_versions (
    dataset_name text primary key,
    loaded_on timestamptz not null default now(),
    source_date date not null,
    row_count integer not null default 0,
    notes text,
    created_at timestamptz not null default now()
);

-- 8. reports (patient-submitted issue reports)
create table if not exists public.reports (
    id uuid primary key default gen_random_uuid(),
    brand_product_id uuid references public.brand_products(id) on delete set null,
    pharmacy_name text not null
        check (char_length(trim(pharmacy_name)) between 1 and 200),
    pharmacy_licence_no text
        check (pharmacy_licence_no is null or char_length(pharmacy_licence_no) <= 100),
    report_type text not null
        check (report_type in (
            'sold_above_mrp',
            'price_above_ceiling',
            'out_of_stock',
            'suspect_batch_or_pack',
            'bill_refused'
        )),
    description text not null
        check (char_length(trim(description)) between 1 and 2000),
    batch_number text
        check (batch_number is null or char_length(batch_number) <= 100),
    created_at timestamptz not null default now()
);

-- =============================================================================
-- Indexes
-- =============================================================================

-- Matching key (salt_normalized, strength, dosage_form) on every table that has all 3 columns
create index if not exists idx_brand_products_match_key
    on public.brand_products (lower(salt_normalized), lower(strength), lower(dosage_form));

create index if not exists idx_brand_products_match_key_exact
    on public.brand_products (salt_normalized, strength, dosage_form);

create index if not exists idx_ceiling_prices_match_key
    on public.ceiling_prices (lower(salt_normalized), lower(strength), lower(dosage_form));

create index if not exists idx_ceiling_prices_match_key_exact
    on public.ceiling_prices (salt_normalized, strength, dosage_form);

create index if not exists idx_jan_aushadhi_match_key
    on public.jan_aushadhi_products (lower(salt_normalized), lower(strength), lower(dosage_form));

create index if not exists idx_jan_aushadhi_match_key_exact
    on public.jan_aushadhi_products (salt_normalized, strength, dosage_form);

-- Trigram indexes for fuzzy search on brand_products
create index if not exists idx_brand_products_brand_name_trgm
    on public.brand_products using gin (brand_name gin_trgm_ops);

create index if not exists idx_brand_products_salt_trgm
    on public.brand_products using gin (salt_normalized gin_trgm_ops);

-- Additional lookup indexes
create index if not exists idx_barcodes_brand_product_id
    on public.barcodes (brand_product_id);

create index if not exists idx_nsq_alerts_batch_key
    on public.nsq_alerts (batch_key);

create index if not exists idx_nsq_alerts_salt_mfr
    on public.nsq_alerts (lower(salt_normalized), lower(manufacturer));

create index if not exists idx_authorities_state
    on public.authorities (lower(state));

-- #############################################################################
-- ## 0002_functions_rls.sql
-- #############################################################################

-- =============================================================================
-- MediCheck Migration 0002: Row-Level Security (RLS) & RPC Functions
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. Enable Row-Level Security on ALL tables
-- -----------------------------------------------------------------------------
alter table public.brand_products enable row level security;
alter table public.barcodes enable row level security;
alter table public.ceiling_prices enable row level security;
alter table public.nsq_alerts enable row level security;
alter table public.jan_aushadhi_products enable row level security;
alter table public.authorities enable row level security;
alter table public.data_versions enable row level security;
alter table public.reports enable row level security;

-- -----------------------------------------------------------------------------
-- 2. RLS Policies
-- Public (anon + authenticated) SELECT on reference tables & data_versions
-- -----------------------------------------------------------------------------
drop policy if exists "Public read brand_products" on public.brand_products;
create policy "Public read brand_products"
    on public.brand_products for select
    to anon, authenticated
    using (true);

drop policy if exists "Public read barcodes" on public.barcodes;
create policy "Public read barcodes"
    on public.barcodes for select
    to anon, authenticated
    using (true);

drop policy if exists "Public read ceiling_prices" on public.ceiling_prices;
create policy "Public read ceiling_prices"
    on public.ceiling_prices for select
    to anon, authenticated
    using (true);

drop policy if exists "Public read nsq_alerts" on public.nsq_alerts;
create policy "Public read nsq_alerts"
    on public.nsq_alerts for select
    to anon, authenticated
    using (true);

drop policy if exists "Public read jan_aushadhi_products" on public.jan_aushadhi_products;
create policy "Public read jan_aushadhi_products"
    on public.jan_aushadhi_products for select
    to anon, authenticated
    using (true);

drop policy if exists "Public read authorities" on public.authorities;
create policy "Public read authorities"
    on public.authorities for select
    to anon, authenticated
    using (true);

drop policy if exists "Public read data_versions" on public.data_versions;
create policy "Public read data_versions"
    on public.data_versions for select
    to anon, authenticated
    using (true);

-- Anon INSERT only on reports (with strict text length checks);
-- NO anon SELECT, UPDATE, or DELETE policies on reports.
drop policy if exists "Anon insert reports" on public.reports;
create policy "Anon insert reports"
    on public.reports for insert
    to anon, authenticated
    with check (
        char_length(trim(pharmacy_name)) between 1 and 200
        and (pharmacy_licence_no is null or char_length(pharmacy_licence_no) <= 100)
        and report_type in (
            'sold_above_mrp',
            'price_above_ceiling',
            'out_of_stock',
            'suspect_batch_or_pack',
            'bill_refused'
        )
        and char_length(trim(description)) between 1 and 2000
        and (batch_number is null or char_length(batch_number) <= 100)
    );

-- -----------------------------------------------------------------------------
-- 3. Postgres RPC Functions (SECURITY INVOKER, STABLE)
-- -----------------------------------------------------------------------------

-- 3.1 search_brands(q text, lim int default 15)
-- Fuzzy match on brand_name and salt_normalized, ranked by trigram similarity.
create or replace function public.search_brands(
    q text,
    lim int default 15
)
returns table (
    id uuid,
    brand_name text,
    manufacturer text,
    salt_normalized text,
    strength text,
    dosage_form text,
    pack_size numeric,
    pack_unit text,
    printed_mrp numeric,
    price_per_unit numeric,
    mrp_source text,
    mrp_date date,
    schedule_status text,
    notes text,
    similarity_score real
)
language sql
stable
security invoker
set search_path = public
as $$
    with cleaned as (
        select trim(coalesce(q, '')) as query_str,
               least(greatest(coalesce(lim, 15), 1), 100) as max_rows
    )
    select
        bp.id,
        bp.brand_name,
        bp.manufacturer,
        bp.salt_normalized,
        bp.strength,
        bp.dosage_form,
        bp.pack_size,
        bp.pack_unit,
        bp.printed_mrp,
        bp.price_per_unit,
        bp.mrp_source,
        bp.mrp_date,
        bp.schedule_status,
        bp.notes,
        greatest(
            similarity(bp.brand_name, c.query_str),
            similarity(bp.salt_normalized, c.query_str),
            case
                when bp.brand_name ilike (c.query_str || '%') then 0.85::real
                when bp.salt_normalized ilike (c.query_str || '%') then 0.80::real
                when bp.brand_name ilike ('%' || c.query_str || '%') then 0.65::real
                when bp.salt_normalized ilike ('%' || c.query_str || '%') then 0.60::real
                else 0.0::real
            end
        ) as similarity_score
    from public.brand_products bp
    cross join cleaned c
    where c.query_str <> ''
      and (
          bp.brand_name % c.query_str
          or bp.salt_normalized % c.query_str
          or bp.brand_name ilike ('%' || c.query_str || '%')
          or bp.salt_normalized ilike ('%' || c.query_str || '%')
          or similarity(bp.brand_name, c.query_str) >= 0.15
          or similarity(bp.salt_normalized, c.query_str) >= 0.15
      )
    order by similarity_score desc, bp.brand_name asc
    limit (select max_rows from cleaned);
$$;

-- 3.2 lookup_by_barcode(code text)
-- Returns the matching brand_product row (or null / empty set if not found).
create or replace function public.lookup_by_barcode(
    code text
)
returns public.brand_products
language sql
stable
security invoker
set search_path = public
as $$
    select bp.*
    from public.barcodes b
    join public.brand_products bp on bp.id = b.brand_product_id
    where b.barcode = trim(coalesce(code, ''))
    limit 1;
$$;

-- 3.3 medicine_check(p_brand_product_id uuid, p_batch text default null)
-- Comprehensive price, ceiling, cheaper equivalents, and CDSCO batch check.
create or replace function public.medicine_check(
    p_brand_product_id uuid,
    p_batch text default null
)
returns jsonb
language plpgsql
stable
security invoker
set search_path = public
as $$
declare
    -- Configurable GST allowance constant (default 5% = 0.05) since NPPA ceiling prices exclude GST
    c_gst_allowance constant numeric := 0.05;
    c_safety_note constant text := 'Information only. Do not change or stop a prescribed medicine without asking your doctor or pharmacist.';

    v_product public.brand_products%rowtype;
    v_ceiling public.ceiling_prices%rowtype;
    v_has_ceiling boolean := false;
    v_effective_ceiling_with_gst numeric := null;
    v_ceiling_status text := 'no_ceiling';
    v_gst_explanation text;

    v_equivalents jsonb := '[]'::jsonb;
    v_has_cheaper boolean := false;

    v_normalized_batch text := null;
    v_batch_alert record;
    v_batch_flagged boolean := false;
    v_batch_alert_json jsonb := null;
    v_mfr_salt_alert_count integer := 0;

    v_data_dates jsonb := '{}'::jsonb;
    v_labels text[] := array[]::text[];
begin
    -- 1. Fetch product
    select *
    into v_product
    from public.brand_products
    where id = p_brand_product_id;

    if not found then
        return null;
    end if;

    -- 2. Match NPPA ceiling price on (salt_normalized, strength, dosage_form) + compatible pack_unit
    select cp.*
    into v_ceiling
    from public.ceiling_prices cp
    where lower(cp.salt_normalized) = lower(v_product.salt_normalized)
      and lower(cp.strength) = lower(v_product.strength)
      and lower(cp.dosage_form) = lower(v_product.dosage_form)
      and (
          lower(cp.pack_unit) = lower(v_product.pack_unit)
          or trim(trailing 's' from lower(cp.pack_unit)) = trim(trailing 's' from lower(v_product.pack_unit))
      )
    order by cp.effective_date desc nulls last, cp.created_at desc
    limit 1;

    if found then
        v_has_ceiling := true;
        v_effective_ceiling_with_gst := round(v_ceiling.ceiling_price * (1 + c_gst_allowance), 4);

        if v_product.price_per_unit <= v_effective_ceiling_with_gst then
            v_ceiling_status := 'within';
            v_labels := array_append(v_labels, 'Within ceiling price');
        else
            v_ceiling_status := 'above';
            v_labels := array_append(v_labels, 'Above ceiling price');
        end if;

        v_gst_explanation := format(
            'NPPA ceiling prices exclude GST. A %s%% GST allowance is included when comparing unit price against the ceiling (base ceiling Rs %s/%s, effective threshold Rs %s/%s).',
            round(c_gst_allowance * 100, 1),
            round(v_ceiling.ceiling_price, 2),
            v_ceiling.pack_unit,
            round(v_effective_ceiling_with_gst, 2),
            v_ceiling.pack_unit
        );
    else
        v_ceiling_status := 'no_ceiling';
        v_labels := array_append(v_labels, 'No ceiling price available');
        v_gst_explanation := 'No scheduled NPPA ceiling price matched this salt, strength, dosage form, and unit. Non-scheduled medicines do not have a fixed ceiling price under DPCO.';
    end if;

    -- 3. Cheaper equivalents (same matching key, cheaper price_per_unit, from brand_products + jan_aushadhi_products)
    select coalesce(jsonb_agg(eq_row order by (eq_row->>'price_per_unit')::numeric asc), '[]'::jsonb)
    into v_equivalents
    from (
        -- Jan Aushadhi equivalents
        select jsonb_build_object(
            'id', ja.id,
            'name', ja.generic_name,
            'manufacturer', 'PMBJP (Jan Aushadhi)',
            'ja_product_code', ja.ja_product_code,
            'salt_normalized', ja.salt_normalized,
            'strength', ja.strength,
            'dosage_form', ja.dosage_form,
            'pack_size', ja.pack_size,
            'pack_unit', ja.pack_unit,
            'mrp', ja.mrp,
            'price_per_unit', ja.price_per_unit,
            'savings_per_unit', round(v_product.price_per_unit - ja.price_per_unit, 2),
            'savings_percent', case
                when v_product.price_per_unit > 0 then
                    round(((v_product.price_per_unit - ja.price_per_unit) / v_product.price_per_unit) * 100, 1)
                else 0
            end,
            'is_jan_aushadhi', true
        ) as eq_row
        from public.jan_aushadhi_products ja
        where lower(ja.salt_normalized) = lower(v_product.salt_normalized)
          and lower(ja.strength) = lower(v_product.strength)
          and lower(ja.dosage_form) = lower(v_product.dosage_form)
          and ja.price_per_unit < v_product.price_per_unit

        union all

        -- Other branded equivalents
        select jsonb_build_object(
            'id', bp2.id,
            'name', bp2.brand_name,
            'manufacturer', bp2.manufacturer,
            'ja_product_code', null,
            'salt_normalized', bp2.salt_normalized,
            'strength', bp2.strength,
            'dosage_form', bp2.dosage_form,
            'pack_size', bp2.pack_size,
            'pack_unit', bp2.pack_unit,
            'mrp', bp2.printed_mrp,
            'price_per_unit', bp2.price_per_unit,
            'savings_per_unit', round(v_product.price_per_unit - bp2.price_per_unit, 2),
            'savings_percent', case
                when v_product.price_per_unit > 0 then
                    round(((v_product.price_per_unit - bp2.price_per_unit) / v_product.price_per_unit) * 100, 1)
                else 0
            end,
            'is_jan_aushadhi', false
        ) as eq_row
        from public.brand_products bp2
        where bp2.id <> v_product.id
          and lower(bp2.salt_normalized) = lower(v_product.salt_normalized)
          and lower(bp2.strength) = lower(v_product.strength)
          and lower(bp2.dosage_form) = lower(v_product.dosage_form)
          and bp2.price_per_unit < v_product.price_per_unit
    ) combined;

    if jsonb_array_length(v_equivalents) > 0 then
        v_has_cheaper := true;
        v_labels := array_append(v_labels, 'Cheaper equivalent available');
    end if;

    -- 4. Batch check & Manufacturer+Salt info alert count
    select count(*)::integer
    into v_mfr_salt_alert_count
    from public.nsq_alerts na
    where lower(na.salt_normalized) = lower(v_product.salt_normalized)
      and lower(coalesce(na.manufacturer, '')) = lower(v_product.manufacturer);

    if p_batch is not null and trim(p_batch) <> '' then
        v_normalized_batch := upper(regexp_replace(p_batch, '\s', '', 'g'));

        select
            na.id,
            na.alert_month,
            na.category,
            na.drug_name,
            na.brand_name,
            na.batch_number,
            na.manufacturer,
            na.manufacturing_date,
            na.expiry_date,
            na.failure_reason,
            na.testing_lab,
            na.source_url,
            na.source_date
        into v_batch_alert
        from public.nsq_alerts na
        where na.batch_key = v_normalized_batch
        order by na.source_date desc nulls last, na.created_at desc
        limit 1;

        if found then
            v_batch_flagged := true;
            v_batch_alert_json := jsonb_build_object(
                'id', v_batch_alert.id,
                'alert_month', v_batch_alert.alert_month,
                'category', v_batch_alert.category,
                'drug_name', v_batch_alert.drug_name,
                'brand_name', v_batch_alert.brand_name,
                'batch_number', v_batch_alert.batch_number,
                'manufacturer', v_batch_alert.manufacturer,
                'manufacturing_date', v_batch_alert.manufacturing_date,
                'expiry_date', v_batch_alert.expiry_date,
                'failure_reason', v_batch_alert.failure_reason,
                'testing_lab', v_batch_alert.testing_lab,
                'source_url', v_batch_alert.source_url,
                'source_date', v_batch_alert.source_date
            );
            v_labels := array_append(v_labels, 'Batch flagged by CDSCO');
        else
            v_batch_flagged := false;
            v_labels := array_append(v_labels, 'Batch not found in latest CDSCO lists');
        end if;
    end if;

    -- 5. Dataset freshness dates from data_versions
    select coalesce(
        jsonb_object_agg(dv.dataset_name, dv.source_date),
        '{}'::jsonb
    )
    into v_data_dates
    from public.data_versions dv;

    -- 6. Build complete JSONB payload
    return jsonb_build_object(
        'product', jsonb_build_object(
            'id', v_product.id,
            'brand_name', v_product.brand_name,
            'manufacturer', v_product.manufacturer,
            'salt_normalized', v_product.salt_normalized,
            'strength', v_product.strength,
            'dosage_form', v_product.dosage_form,
            'pack_size', v_product.pack_size,
            'pack_unit', v_product.pack_unit,
            'printed_mrp', v_product.printed_mrp,
            'price_per_unit', v_product.price_per_unit,
            'mrp_source', v_product.mrp_source,
            'mrp_date', v_product.mrp_date,
            'schedule_status', v_product.schedule_status,
            'notes', v_product.notes
        ),
        'price', jsonb_build_object(
            'printed_mrp', v_product.printed_mrp,
            'price_per_unit', v_product.price_per_unit,
            'ceiling_status', v_ceiling_status,
            'gst_allowance_percent', round(c_gst_allowance * 100, 1),
            'effective_ceiling_per_unit_with_gst', v_effective_ceiling_with_gst,
            'gst_note', v_gst_explanation,
            'ceiling_row', case
                when v_has_ceiling then jsonb_build_object(
                    'id', v_ceiling.id,
                    'salt_normalized', v_ceiling.salt_normalized,
                    'strength', v_ceiling.strength,
                    'dosage_form', v_ceiling.dosage_form,
                    'pack_unit', v_ceiling.pack_unit,
                    'ceiling_price', v_ceiling.ceiling_price,
                    'gst_note', v_ceiling.gst_note,
                    'effective_date', v_ceiling.effective_date,
                    'notification_ref', v_ceiling.notification_ref,
                    'source_url', v_ceiling.source_url,
                    'source_date', v_ceiling.source_date
                )
                else null
            end
        ),
        'equivalents', v_equivalents,
        'batch', jsonb_build_object(
            'batch_queried', p_batch,
            'batch_key', v_normalized_batch,
            'checked', (p_batch is not null and trim(p_batch) <> ''),
            'flagged', v_batch_flagged,
            'alert', v_batch_alert_json,
            'manufacturer_salt_recent_alert_count', v_mfr_salt_alert_count,
            'manufacturer_salt_note', format(
                'Historical alert count (%s) for this manufacturer and salt is provided as background information only and does not flag your specific batch.',
                v_mfr_salt_alert_count
            )
        ),
        'data_dates', v_data_dates,
        'labels', to_jsonb(v_labels),
        'safety_note', c_safety_note
    );
end;
$$;

-- 3.4 get_authorities(p_state text default null, p_handles text default null)
-- Returns national authorities plus matching state/issue-type authorities.
create or replace function public.get_authorities(
    p_state text default null,
    p_handles text default null
)
returns setof public.authorities
language sql
stable
security invoker
set search_path = public
as $$
    select a.*
    from public.authorities a
    where (
        p_state is null
        or trim(p_state) = ''
        or lower(a.state) = 'all'
        or lower(a.state) = 'national'
        or a.state is null
        or lower(a.state) = lower(trim(p_state))
    )
    and (
        p_handles is null
        or trim(p_handles) = ''
        or a.handles ilike ('%' || trim(p_handles) || '%')
    )
    order by
        case
            when lower(coalesce(a.state, 'national')) in ('all', 'national') then 0
            else 1
        end asc,
        a.authority_name asc;
$$;

-- Grant execute permissions on RPC functions to anon and authenticated roles
grant execute on function public.search_brands(text, integer) to anon, authenticated;
grant execute on function public.lookup_by_barcode(text) to anon, authenticated;
grant execute on function public.medicine_check(uuid, text) to anon, authenticated;
grant execute on function public.get_authorities(text, text) to anon, authenticated;

-- #############################################################################
-- ## 0003_alignment.sql
-- #############################################################################

-- =============================================================================
-- MediCheck Migration 0003: Align with data spec
--  A1. authorities.handles = comma-separated {price, shortage, quality, bill_refusal}
--  A2. authorities.state is NULL for central bodies
--  A3. normalize_pack_unit() used everywhere pack units are compared
--  Also: nsq_alerts.batch_number becomes nullable (rows with notes only)
-- =============================================================================

-- -----------------------------------------------------------------------------
-- A3. Reusable pack-unit normaliser: lowercase, strip leading "per ", strip trailing "s"
--     'per tablet' = 'tablet' = 'tablets' = 'Tablets'
-- -----------------------------------------------------------------------------
create or replace function public.normalize_pack_unit(u text)
returns text
language sql
immutable
security invoker
set search_path = public
as $$
    select nullif(
        regexp_replace(
            regexp_replace(lower(btrim(coalesce(u, ''))), '^per\s+', ''),
            's$', ''
        ),
        ''
    );
$$;

grant execute on function public.normalize_pack_unit(text) to anon, authenticated;

-- -----------------------------------------------------------------------------
-- nsq_alerts: allow empty batch_number (generated batch_key becomes NULL)
-- -----------------------------------------------------------------------------
alter table public.nsq_alerts alter column batch_number drop not null;

-- -----------------------------------------------------------------------------
-- A1 + A2: authorities data shape
-- -----------------------------------------------------------------------------
comment on column public.authorities.handles is
    'Comma-separated list (no spaces) of issue types handled, from: price, shortage, quality, bill_refusal.';
comment on column public.authorities.state is
    'NULL for central bodies; state name for state_drug_controller rows.';

-- Convert legacy rows (old report-type / pipe format, state = All/National)
update public.authorities
set state = null
where state is not null and lower(btrim(state)) in ('all', 'national');

update public.authorities a
set handles = (
    select string_agg(distinct m.h, ',' order by m.h)
    from unnest(string_to_array(regexp_replace(a.handles, '\s*[|,]\s*', ',', 'g'), ',')) as t(raw)
    cross join lateral (
        select case t.raw
            when 'sold_above_mrp'        then 'price'
            when 'price_above_ceiling'   then 'price'
            when 'out_of_stock'          then 'shortage'
            when 'suspect_batch_or_pack' then 'quality'
            when 'bill_refused'          then 'bill_refusal'
            else t.raw
        end as h
    ) m
)
where a.handles is not null;

alter table public.authorities drop constraint if exists authorities_handles_check;
alter table public.authorities
    add constraint authorities_handles_check
    check (
        handles is null
        or handles ~ '^(price|shortage|quality|bill_refusal)(,(price|shortage|quality|bill_refusal))*$'
    ) not valid;

-- -----------------------------------------------------------------------------
-- get_authorities: new signature (adds p_report_type); drop the old overload first
-- -----------------------------------------------------------------------------
drop function if exists public.get_authorities(text, text);

create or replace function public.get_authorities(
    p_state text default null,
    p_handles text default null,
    p_report_type text default null
)
returns setof public.authorities
language plpgsql
stable
security invoker
set search_path = public
as $$
declare
    v_report_handle text := null;
    v_handle text := nullif(lower(btrim(coalesce(p_handles, ''))), '');
begin
    -- report_type -> handle mapping
    if p_report_type is not null and btrim(p_report_type) <> '' then
        v_report_handle := case btrim(p_report_type)
            when 'sold_above_mrp'        then 'price'
            when 'price_above_ceiling'   then 'price'
            when 'out_of_stock'          then 'shortage'
            when 'suspect_batch_or_pack' then 'quality'
            when 'bill_refused'          then 'bill_refusal'
            else null
        end;
        if v_report_handle is null then
            raise exception 'Unknown report_type: %', p_report_type;
        end if;
    end if;

    return query
    select a.*
    from public.authorities a
    where (
            a.state is null  -- central bodies always included
            or (nullif(btrim(coalesce(p_state, '')), '') is not null
                and lower(btrim(a.state)) = lower(btrim(p_state)))
          )
      and (v_handle is null
           or v_handle = any (string_to_array(replace(coalesce(a.handles, ''), ' ', ''), ',')))
      and (v_report_handle is null
           or v_report_handle = any (string_to_array(replace(coalesce(a.handles, ''), ' ', ''), ',')))
    order by (a.state is not null) asc, a.authority_name asc;
end;
$$;

grant execute on function public.get_authorities(text, text, text) to anon, authenticated;

-- -----------------------------------------------------------------------------
-- medicine_check: uses normalize_pack_unit for ceiling AND equivalents matching
-- -----------------------------------------------------------------------------
create or replace function public.medicine_check(
    p_brand_product_id uuid,
    p_batch text default null
)
returns jsonb
language plpgsql
stable
security invoker
set search_path = public
as $$
declare
    -- Configurable GST allowance (0.05 = 5%). NPPA ceiling prices exclude GST.
    c_gst_allowance constant numeric := 0.05;
    c_safety_note constant text := 'Information only. Do not change or stop a prescribed medicine without asking your doctor or pharmacist.';

    v_product public.brand_products%rowtype;
    v_ceiling public.ceiling_prices%rowtype;
    v_has_ceiling boolean := false;
    v_effective_ceiling_with_gst numeric := null;
    v_ceiling_status text := 'no_ceiling';
    v_gst_explanation text;

    v_equivalents jsonb := '[]'::jsonb;

    v_normalized_batch text := null;
    v_batch_alert record;
    v_batch_flagged boolean := false;
    v_batch_alert_json jsonb := null;
    v_mfr_salt_alert_count integer := 0;

    v_data_dates jsonb := '{}'::jsonb;
    v_labels text[] := array[]::text[];
begin
    select * into v_product from public.brand_products where id = p_brand_product_id;
    if not found then
        return null;
    end if;

    -- Ceiling: matching key + compatible (normalised) pack unit
    select cp.* into v_ceiling
    from public.ceiling_prices cp
    where lower(cp.salt_normalized) = lower(v_product.salt_normalized)
      and lower(cp.strength) = lower(v_product.strength)
      and lower(cp.dosage_form) = lower(v_product.dosage_form)
      and public.normalize_pack_unit(cp.pack_unit) = public.normalize_pack_unit(v_product.pack_unit)
    order by cp.effective_date desc nulls last, cp.created_at desc
    limit 1;

    if found then
        v_has_ceiling := true;
        v_effective_ceiling_with_gst := round(v_ceiling.ceiling_price * (1 + c_gst_allowance), 4);

        if v_product.price_per_unit <= v_effective_ceiling_with_gst then
            v_ceiling_status := 'within';
            v_labels := array_append(v_labels, 'Within ceiling price');
        else
            v_ceiling_status := 'above';
            v_labels := array_append(v_labels, 'Above ceiling price');
        end if;

        v_gst_explanation := format(
            'NPPA ceiling prices exclude GST. A %s%% GST allowance is included when comparing unit price against the ceiling (base ceiling Rs %s/%s, effective threshold Rs %s/%s).',
            round(c_gst_allowance * 100, 1),
            round(v_ceiling.ceiling_price, 2),
            v_ceiling.pack_unit,
            round(v_effective_ceiling_with_gst, 2),
            v_ceiling.pack_unit
        );
    else
        v_labels := array_append(v_labels, 'No ceiling price available');
        v_gst_explanation := 'No scheduled NPPA ceiling price matched this salt, strength, dosage form, and unit. Non-scheduled medicines do not have a fixed ceiling price under DPCO.';
    end if;

    -- Cheaper equivalents (same key + compatible pack unit), Jan Aushadhi and branded
    select coalesce(jsonb_agg(eq_row order by (eq_row->>'price_per_unit')::numeric asc), '[]'::jsonb)
    into v_equivalents
    from (
        select jsonb_build_object(
            'id', ja.id,
            'name', ja.generic_name,
            'manufacturer', 'PMBJP (Jan Aushadhi)',
            'ja_product_code', ja.ja_product_code,
            'salt_normalized', ja.salt_normalized,
            'strength', ja.strength,
            'dosage_form', ja.dosage_form,
            'pack_size', ja.pack_size,
            'pack_unit', ja.pack_unit,
            'mrp', ja.mrp,
            'price_per_unit', ja.price_per_unit,
            'savings_per_unit', round(v_product.price_per_unit - ja.price_per_unit, 2),
            'savings_percent', case when v_product.price_per_unit > 0
                then round(((v_product.price_per_unit - ja.price_per_unit) / v_product.price_per_unit) * 100, 1)
                else 0 end,
            'is_jan_aushadhi', true
        ) as eq_row
        from public.jan_aushadhi_products ja
        where lower(ja.salt_normalized) = lower(v_product.salt_normalized)
          and lower(ja.strength) = lower(v_product.strength)
          and lower(ja.dosage_form) = lower(v_product.dosage_form)
          and public.normalize_pack_unit(ja.pack_unit) = public.normalize_pack_unit(v_product.pack_unit)
          and ja.price_per_unit < v_product.price_per_unit

        union all

        select jsonb_build_object(
            'id', bp2.id,
            'name', bp2.brand_name,
            'manufacturer', bp2.manufacturer,
            'ja_product_code', null,
            'salt_normalized', bp2.salt_normalized,
            'strength', bp2.strength,
            'dosage_form', bp2.dosage_form,
            'pack_size', bp2.pack_size,
            'pack_unit', bp2.pack_unit,
            'mrp', bp2.printed_mrp,
            'price_per_unit', bp2.price_per_unit,
            'savings_per_unit', round(v_product.price_per_unit - bp2.price_per_unit, 2),
            'savings_percent', case when v_product.price_per_unit > 0
                then round(((v_product.price_per_unit - bp2.price_per_unit) / v_product.price_per_unit) * 100, 1)
                else 0 end,
            'is_jan_aushadhi', false
        ) as eq_row
        from public.brand_products bp2
        where bp2.id <> v_product.id
          and lower(bp2.salt_normalized) = lower(v_product.salt_normalized)
          and lower(bp2.strength) = lower(v_product.strength)
          and lower(bp2.dosage_form) = lower(v_product.dosage_form)
          and public.normalize_pack_unit(bp2.pack_unit) = public.normalize_pack_unit(v_product.pack_unit)
          and bp2.price_per_unit < v_product.price_per_unit
    ) combined;

    if jsonb_array_length(v_equivalents) > 0 then
        v_labels := array_append(v_labels, 'Cheaper equivalent available');
    end if;

    -- Info-only count for manufacturer + salt (NOT a flag)
    select count(*)::integer into v_mfr_salt_alert_count
    from public.nsq_alerts na
    where lower(na.salt_normalized) = lower(v_product.salt_normalized)
      and lower(coalesce(na.manufacturer, '')) = lower(v_product.manufacturer);

    -- Batch check
    if p_batch is not null and btrim(p_batch) <> '' then
        v_normalized_batch := upper(regexp_replace(p_batch, '\s', '', 'g'));

        select na.id, na.alert_month, na.category, na.drug_name, na.brand_name, na.batch_number,
               na.manufacturer, na.manufacturing_date, na.expiry_date, na.failure_reason,
               na.testing_lab, na.source_url, na.source_date
        into v_batch_alert
        from public.nsq_alerts na
        where na.batch_key = v_normalized_batch
        order by na.source_date desc nulls last, na.created_at desc
        limit 1;

        if found then
            v_batch_flagged := true;
            v_batch_alert_json := jsonb_build_object(
                'id', v_batch_alert.id,
                'alert_month', v_batch_alert.alert_month,
                'category', v_batch_alert.category,
                'drug_name', v_batch_alert.drug_name,
                'brand_name', v_batch_alert.brand_name,
                'batch_number', v_batch_alert.batch_number,
                'manufacturer', v_batch_alert.manufacturer,
                'manufacturing_date', v_batch_alert.manufacturing_date,
                'expiry_date', v_batch_alert.expiry_date,
                'failure_reason', v_batch_alert.failure_reason,
                'testing_lab', v_batch_alert.testing_lab,
                'source_url', v_batch_alert.source_url,
                'source_date', v_batch_alert.source_date
            );
            v_labels := array_append(v_labels, 'Batch flagged by CDSCO');
        else
            v_labels := array_append(v_labels, 'Batch not found in latest CDSCO lists');
        end if;
    end if;

    select coalesce(jsonb_object_agg(dv.dataset_name, dv.source_date), '{}'::jsonb)
    into v_data_dates
    from public.data_versions dv;

    return jsonb_build_object(
        'product', jsonb_build_object(
            'id', v_product.id,
            'brand_name', v_product.brand_name,
            'manufacturer', v_product.manufacturer,
            'salt_normalized', v_product.salt_normalized,
            'strength', v_product.strength,
            'dosage_form', v_product.dosage_form,
            'pack_size', v_product.pack_size,
            'pack_unit', v_product.pack_unit,
            'printed_mrp', v_product.printed_mrp,
            'price_per_unit', v_product.price_per_unit,
            'mrp_source', v_product.mrp_source,
            'mrp_date', v_product.mrp_date,
            'schedule_status', v_product.schedule_status,
            'notes', v_product.notes
        ),
        'price', jsonb_build_object(
            'printed_mrp', v_product.printed_mrp,
            'price_per_unit', v_product.price_per_unit,
            'ceiling_status', v_ceiling_status,
            'gst_allowance_percent', round(c_gst_allowance * 100, 1),
            'effective_ceiling_per_unit_with_gst', v_effective_ceiling_with_gst,
            'gst_note', v_gst_explanation,
            'ceiling_row', case when v_has_ceiling then jsonb_build_object(
                'id', v_ceiling.id,
                'salt_normalized', v_ceiling.salt_normalized,
                'strength', v_ceiling.strength,
                'dosage_form', v_ceiling.dosage_form,
                'pack_unit', v_ceiling.pack_unit,
                'ceiling_price', v_ceiling.ceiling_price,
                'gst_note', v_ceiling.gst_note,
                'effective_date', v_ceiling.effective_date,
                'notification_ref', v_ceiling.notification_ref,
                'source_url', v_ceiling.source_url,
                'source_date', v_ceiling.source_date
            ) else null end
        ),
        'equivalents', v_equivalents,
        'batch', jsonb_build_object(
            'batch_queried', p_batch,
            'batch_key', v_normalized_batch,
            'checked', (p_batch is not null and btrim(p_batch) <> ''),
            'flagged', v_batch_flagged,
            'alert', v_batch_alert_json,
            'manufacturer_salt_recent_alert_count', v_mfr_salt_alert_count,
            'manufacturer_salt_note', format(
                'Historical alert count (%s) for this manufacturer and salt is provided as background information only and does not flag your specific batch.',
                v_mfr_salt_alert_count
            )
        ),
        'data_dates', v_data_dates,
        'labels', to_jsonb(v_labels),
        'safety_note', c_safety_note
    );
end;
$$;

grant execute on function public.medicine_check(uuid, text) to anon, authenticated;

-- #############################################################################
-- ## 0004_public_log.sql
-- #############################################################################

-- =============================================================================
-- MediCheck Migration 0004: Tamper-evident public log (hash chain + Merkle root)
--
-- Design notes
--  * canonical_json(payload) := payload::text. jsonb has a stable key order
--    (shorter keys first, then bytewise), so the same payload always renders identically.
--  * entry_hash = sha256_hex( prev_hash || payload::text || entry_type || iso_utc(created_at) )
--    where iso_utc = 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"' in UTC. Genesis prev_hash = 64 zeros.
--  * The log is append-only. UPDATE/DELETE/TRUNCATE raise an exception for everyone
--    (including service role). Corrections are appended as new entries.
--  * The chain proves a record is unchanged after filing; NOT that it was true when filed.
--  * Limitation: a database owner could drop the trigger; periodic anchoring
--    (anchor_snapshots + scripts/anchor.ts) is what detects that.
--  * report_filed payloads hold NO pharmacy name/licence and NO free text: only a salted
--    pharmacy_ref (pepper kept in private_settings, readable only by definer functions).
--  * reports RLS (0002) does not restrict `id`, so clients may supply an explicit id.
--  * report_id uniqueness is enforced per report_filed entry (partial unique index) so that
--    later status_change / moderation_removed entries can reference the same report.
-- =============================================================================

create extension if not exists pgcrypto;

-- -----------------------------------------------------------------------------
-- Hash helpers (built-in sha256, no dependency on where pgcrypto is installed)
-- -----------------------------------------------------------------------------
create or replace function public.sha256_hex(p_text text)
returns text
language sql
immutable
set search_path = public, pg_temp
as $$
    select encode(sha256(convert_to(coalesce(p_text, ''), 'UTF8')), 'hex');
$$;

create or replace function public.iso_utc(p_ts timestamptz)
returns text
language sql
stable
set search_path = public, pg_temp
as $$
    select to_char(p_ts at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"');
$$;

create or replace function public.log_entry_hash(
    p_prev_hash text,
    p_payload jsonb,
    p_entry_type text,
    p_created_at timestamptz
)
returns text
language sql
stable
set search_path = public, pg_temp
as $$
    select public.sha256_hex(
        p_prev_hash || p_payload::text || p_entry_type || public.iso_utc(p_created_at)
    );
$$;

-- -----------------------------------------------------------------------------
-- private_settings: secret pepper for pharmacy_ref. RLS on, NO policies, no grants:
-- only SECURITY DEFINER functions with a fixed search_path can read it.
-- -----------------------------------------------------------------------------
create table if not exists public.private_settings (
    key text primary key,
    value text not null
);

alter table public.private_settings enable row level security;
revoke all on public.private_settings from public, anon, authenticated, service_role;

insert into public.private_settings (key, value)
values ('log_pepper', gen_random_uuid()::text)
on conflict (key) do nothing;

-- pharmacy_ref = sha256_hex( upper(remove-whitespace(licence-or-name)) || pepper )
-- The public log stores only this reference, never the pharmacy name or licence number.
create or replace function public.pharmacy_ref(p_licence_or_name text)
returns text
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
    v_pepper text;
begin
    if p_licence_or_name is null or btrim(p_licence_or_name) = '' then
        return null;
    end if;
    select value into v_pepper from public.private_settings where key = 'log_pepper';
    if v_pepper is null then
        raise exception 'log pepper is not configured';
    end if;
    return public.sha256_hex(upper(regexp_replace(p_licence_or_name, '\s', '', 'g')) || v_pepper);
end;
$$;

revoke execute on function public.pharmacy_ref(text) from public, anon, authenticated;

-- -----------------------------------------------------------------------------
-- public_log
-- -----------------------------------------------------------------------------
create table if not exists public.public_log (
    seq bigint generated always as identity primary key,
    report_id uuid not null,
    entry_type text not null
        check (entry_type in ('report_filed', 'status_change', 'moderation_removed')),
    payload jsonb not null,
    prev_hash text not null,
    entry_hash text not null,
    created_at timestamptz not null default now()
);

create unique index if not exists public_log_report_filed_uniq
    on public.public_log (report_id) where entry_type = 'report_filed';
create index if not exists public_log_report_id_idx on public.public_log (report_id);

alter table public.public_log enable row level security;

drop policy if exists "Public read public_log" on public.public_log;
create policy "Public read public_log"
    on public.public_log for select
    to anon, authenticated
    using (true);

revoke all on public.public_log from public, anon, authenticated, service_role;
grant select on public.public_log to anon, authenticated, service_role;

-- Immutability: blocks everyone, including service role
create or replace function public.public_log_block_mutation()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
    raise exception 'public_log is append-only: % is not allowed. Append a correcting entry instead.', tg_op
        using errcode = '42501';
end;
$$;

drop trigger if exists public_log_no_update_delete on public.public_log;
create trigger public_log_no_update_delete
    before update or delete on public.public_log
    for each row execute function public.public_log_block_mutation();

drop trigger if exists public_log_no_truncate on public.public_log;
create trigger public_log_no_truncate
    before truncate on public.public_log
    for each statement execute function public.public_log_block_mutation();

-- -----------------------------------------------------------------------------
-- Appending (the only write path)
-- -----------------------------------------------------------------------------
create or replace function public.append_log_entry(
    p_report_id uuid,
    p_entry_type text,
    p_payload jsonb
)
returns public.public_log
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
    v_prev text;
    v_ts timestamptz := clock_timestamp();
    v_row public.public_log;
begin
    -- Serialise appends so the chain cannot fork
    perform pg_advisory_xact_lock(hashtextextended('medicheck_public_log', 0));

    select entry_hash into v_prev from public.public_log order by seq desc limit 1;
    v_prev := coalesce(v_prev, repeat('0', 64));

    insert into public.public_log (report_id, entry_type, payload, prev_hash, entry_hash, created_at)
    values (
        p_report_id, p_entry_type, p_payload, v_prev,
        public.log_entry_hash(v_prev, p_payload, p_entry_type, v_ts),
        v_ts
    )
    returning * into v_row;

    return v_row;
end;
$$;

-- Payload for report_filed: NON-PERSONAL fields only. Never the free-text description.
create or replace function public.build_report_log_payload(r public.reports)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
    v_brand public.brand_products%rowtype;
begin
    if r.brand_product_id is not null then
        select * into v_brand from public.brand_products where id = r.brand_product_id;
    end if;

    return jsonb_build_object(
        'report_id', r.id,
        'report_type', r.report_type,
        -- anonymised: pharmacy name / licence stay only in the private reports table
        'pharmacy_ref', public.pharmacy_ref(coalesce(nullif(btrim(r.pharmacy_licence_no), ''), r.pharmacy_name)),
        'salt_normalized', v_brand.salt_normalized,
        'strength', v_brand.strength,
        'dosage_form', v_brand.dosage_form,
        'brand_name', v_brand.brand_name,
        'batch_number', r.batch_number,
        'filed_at', public.iso_utc(r.created_at)
    );
end;
$$;

create or replace function public.trg_report_to_public_log()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
    perform public.append_log_entry(new.id, 'report_filed', public.build_report_log_payload(new));
    return new;
end;
$$;

drop trigger if exists reports_to_public_log on public.reports;
create trigger reports_to_public_log
    after insert on public.reports
    for each row execute function public.trg_report_to_public_log();

-- Service-role-only: append a correction (never edits earlier entries)
create or replace function public.append_log_correction(
    p_report_id uuid,
    p_entry_type text,
    p_payload jsonb
)
returns public.public_log
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
    if p_entry_type not in ('status_change', 'moderation_removed') then
        raise exception 'Corrections must be status_change or moderation_removed';
    end if;
    if not exists (select 1 from public.public_log where report_id = p_report_id and entry_type = 'report_filed') then
        raise exception 'No report_filed entry for report %', p_report_id;
    end if;
    return public.append_log_entry(
        p_report_id, p_entry_type,
        coalesce(p_payload, '{}'::jsonb) || jsonb_build_object('report_id', p_report_id)
    );
end;
$$;

revoke execute on function public.append_log_entry(uuid, text, jsonb) from public, anon, authenticated;
revoke execute on function public.build_report_log_payload(public.reports) from public, anon, authenticated;
revoke execute on function public.append_log_correction(uuid, text, jsonb) from public, anon, authenticated;
grant execute on function public.append_log_correction(uuid, text, jsonb) to service_role;

-- Backfill existing reports in created_at order (no reports are deleted)
do $$
declare
    r public.reports;
begin
    for r in
        select rp.* from public.reports rp
        where not exists (
            select 1 from public.public_log l where l.report_id = rp.id and l.entry_type = 'report_filed'
        )
        order by rp.created_at, rp.id
    loop
        perform public.append_log_entry(r.id, 'report_filed', public.build_report_log_payload(r));
    end loop;
end;
$$;

-- -----------------------------------------------------------------------------
-- anchor_snapshots + Merkle root
-- -----------------------------------------------------------------------------
create table if not exists public.anchor_snapshots (
    id uuid primary key default gen_random_uuid(),
    root_hash text not null,
    entry_count bigint not null,
    last_seq bigint not null,
    computed_at timestamptz not null default now(),
    anchor_method text not null default 'none' check (anchor_method in ('none', 'opentimestamps')),
    anchor_proof text null
);

alter table public.anchor_snapshots enable row level security;

drop policy if exists "Public read anchor_snapshots" on public.anchor_snapshots;
create policy "Public read anchor_snapshots"
    on public.anchor_snapshots for select
    to anon, authenticated
    using (true);

revoke all on public.anchor_snapshots from public, anon, authenticated;
grant select on public.anchor_snapshots to anon, authenticated;
grant select, insert, update on public.anchor_snapshots to service_role;

-- Merkle root over entry_hash values in seq order; pairwise sha256 of concatenated hex;
-- the last node is duplicated when a level has an odd count.
create or replace function public.compute_merkle_root(p_up_to_seq bigint default null)
returns text
language plpgsql
stable
security invoker
set search_path = public, pg_temp
as $$
declare
    v_level text[];
    v_next text[];
    v_n int;
    v_i int;
begin
    select array_agg(entry_hash order by seq) into v_level
    from public.public_log
    where p_up_to_seq is null or seq <= p_up_to_seq;

    if v_level is null then
        return null;
    end if;

    while array_length(v_level, 1) > 1 loop
        v_n := array_length(v_level, 1);
        v_next := array[]::text[];
        v_i := 1;
        while v_i <= v_n loop
            v_next := v_next || public.sha256_hex(v_level[v_i] || coalesce(v_level[v_i + 1], v_level[v_i]));
            v_i := v_i + 2;
        end loop;
        v_level := v_next;
    end loop;

    return v_level[1];
end;
$$;

-- Service role only
create or replace function public.snapshot_log()
returns jsonb
language plpgsql
security invoker
set search_path = public, pg_temp
as $$
declare
    v_last bigint;
    v_count bigint;
    v_root text;
    v_row public.anchor_snapshots;
begin
    select max(seq), count(*) into v_last, v_count from public.public_log;
    if v_last is null then
        raise exception 'public_log is empty; nothing to snapshot';
    end if;
    v_root := public.compute_merkle_root(v_last);

    insert into public.anchor_snapshots (root_hash, entry_count, last_seq)
    values (v_root, v_count, v_last)
    returning * into v_row;

    return to_jsonb(v_row);
end;
$$;

revoke execute on function public.snapshot_log() from public, anon, authenticated;
grant execute on function public.snapshot_log() to service_role;

-- -----------------------------------------------------------------------------
-- Public RPCs (security invoker, stable)
-- -----------------------------------------------------------------------------
create or replace function public.get_receipt(p_report_id uuid)
returns jsonb
language plpgsql
stable
security invoker
set search_path = public, pg_temp
as $$
declare
    e public.public_log;
    v_filed timestamptz;
begin
    select * into e from public.public_log
    where report_id = p_report_id and entry_type = 'report_filed';
    if not found then
        return null;
    end if;

    v_filed := (e.payload->>'filed_at')::timestamptz;

    return jsonb_build_object(
        'report_id', e.report_id,
        'report', e.payload,
        'seq', e.seq,
        'entry_hash', e.entry_hash,
        'prev_hash', e.prev_hash,
        'filed_at', e.payload->>'filed_at',
        'sealed_at', public.iso_utc(e.created_at),
        'days_since_filing', greatest(0, floor(extract(epoch from (now() - v_filed)) / 86400))::int,
        'status', 'filed',
        'authority_response', null,
        'timeline', jsonb_build_array(
            jsonb_build_object('step', 'Report filed', 'at', e.payload->>'filed_at', 'sealed', true),
            jsonb_build_object('step', 'Fingerprint sealed in public log', 'at', public.iso_utc(e.created_at), 'sealed', true)
        ),
        -- Everything needed to recompute entry_hash independently
        'proof', jsonb_build_object(
            'entry_type', e.entry_type,
            'payload_canonical', e.payload::text,
            'sealed_at', public.iso_utc(e.created_at),
            'prev_hash', e.prev_hash,
            'entry_hash', e.entry_hash
        )
    );
end;
$$;

create or replace function public.verify_receipt(p_report_id uuid)
returns jsonb
language plpgsql
stable
security invoker
set search_path = public, pg_temp
as $$
declare
    e public.public_log;
    p public.public_log;
    v_has_prev boolean;
    v_ok boolean := true;
    v_bad text := 'This record or the log before it has been altered.';
begin
    select * into e from public.public_log
    where report_id = p_report_id and entry_type = 'report_filed';
    if not found then
        return jsonb_build_object('valid', false, 'message', 'No sealed record was found for this report.');
    end if;

    -- 1. own hash and payload binding
    if public.log_entry_hash(e.prev_hash, e.payload, e.entry_type, e.created_at) <> e.entry_hash
       or e.payload->>'report_id' <> e.report_id::text then
        v_ok := false;
    end if;

    -- 2. link to the previous entry (and that entry's own hash)
    select * into p from public.public_log where seq < e.seq order by seq desc limit 1;
    v_has_prev := found;
    if v_has_prev then
        if e.prev_hash <> p.entry_hash
           or public.log_entry_hash(p.prev_hash, p.payload, p.entry_type, p.created_at) <> p.entry_hash then
            v_ok := false;
        end if;
    elsif e.prev_hash <> repeat('0', 64) then
        v_ok := false;
    end if;

    if v_ok then
        return jsonb_build_object(
            'valid', true,
            'message', 'This record has not been changed since ' || to_char(e.created_at at time zone 'UTC', 'DD Mon YYYY') || '.'
        );
    end if;
    return jsonb_build_object('valid', false, 'message', v_bad);
end;
$$;

create or replace function public.verify_chain()
returns jsonb
language plpgsql
stable
security invoker
set search_path = public, pg_temp
as $$
declare
    r public.public_log;
    v_expected_prev text := repeat('0', 64);
    v_checked bigint := 0;
begin
    for r in select * from public.public_log order by seq loop
        if r.prev_hash <> v_expected_prev
           or public.log_entry_hash(r.prev_hash, r.payload, r.entry_type, r.created_at) <> r.entry_hash then
            return jsonb_build_object('valid', false, 'entries_checked', v_checked, 'first_bad_seq', r.seq);
        end if;
        v_expected_prev := r.entry_hash;
        v_checked := v_checked + 1;
    end loop;
    return jsonb_build_object('valid', true, 'entries_checked', v_checked, 'first_bad_seq', null);
end;
$$;

create or replace function public.get_latest_snapshot()
returns jsonb
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
    select to_jsonb(s) || jsonb_build_object(
        'entries_since_snapshot', (select count(*) from public.public_log l where l.seq > s.last_seq)
    )
    from public.anchor_snapshots s
    order by s.computed_at desc, s.id
    limit 1;
$$;

grant execute on function public.get_receipt(uuid) to anon, authenticated;
grant execute on function public.verify_receipt(uuid) to anon, authenticated;
grant execute on function public.verify_chain() to anon, authenticated;
grant execute on function public.get_latest_snapshot() to anon, authenticated;
grant execute on function public.compute_merkle_root(bigint) to anon, authenticated, service_role;

-- -----------------------------------------------------------------------------
-- get_pharmacy_case: report counts per type for a pharmacy (last 90 days).
-- Input is the licence number (or the pharmacy name if no licence was given).
-- pharmacy_name is returned ONLY when threshold_met (>= 3 reports of the same type).
-- Counts are numbers of reports; reporters are not yet verified.
-- -----------------------------------------------------------------------------
create or replace function public.get_pharmacy_case(p_licence text)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
    c_window constant interval := interval '90 days';
    c_threshold constant int := 3;
    v_ref text := public.pharmacy_ref(p_licence);
    v_counts jsonb := '{}'::jsonb;
    v_total bigint := 0;
    v_max bigint := 0;
    v_met boolean;
    v_result jsonb;
    v_name text;
begin
    if v_ref is not null then
        select coalesce(jsonb_object_agg(t.report_type, t.c), '{}'::jsonb),
               coalesce(sum(t.c), 0),
               coalesce(max(t.c), 0)
        into v_counts, v_total, v_max
        from (
            select l.payload->>'report_type' as report_type, count(*) as c
            from public.public_log l
            where l.entry_type = 'report_filed'
              and l.payload->>'pharmacy_ref' = v_ref
              and (l.payload->>'filed_at')::timestamptz >= now() - c_window
            group by 1
        ) t;
    end if;

    v_met := v_max >= c_threshold;

    v_result := jsonb_build_object(
        'counts', v_counts,
        'total', v_total,
        'threshold_met', v_met,
        'window_days', 90,
        'note', 'Number of reports filed through MediCheck in the last 90 days. Reporters are not yet verified.'
    );

    if v_met then
        select r.pharmacy_name into v_name
        from public.public_log l
        join public.reports r on r.id = l.report_id
        where l.entry_type = 'report_filed' and l.payload->>'pharmacy_ref' = v_ref
        order by l.seq desc
        limit 1;
        v_result := v_result || jsonb_build_object('pharmacy_name', v_name);
    end if;

    return v_result;
end;
$$;

grant execute on function public.get_pharmacy_case(text) to anon, authenticated;

